import { CostByAgentChart, transformByAgentData } from '../components/CostByAgentChart';

function Dashboard() {
  const { summary } = useCostData();
  const setSelectedAgent = useAppStore(s => s.setSelectedAgent);

  const agentData = summary?.byAgent 
    ? transformByAgentData(summary.byAgent) 
    : [];

  return (
    <CostByAgentChart
      data={agentData}
      onAgentClick={(agentId) => {
        setSelectedAgent(agentId);
        setActiveView('agents');
      }}
      maxAgents={10}
    />
  );
}
```

